CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT, order_number TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', payment_method TEXT NOT NULL, payment_ref TEXT, payment_capture_id TEXT, currency TEXT NOT NULL DEFAULT 'USD', subtotal_cents INTEGER NOT NULL, shipping_cents INTEGER NOT NULL DEFAULT 0, discount_cents INTEGER NOT NULL DEFAULT 0, coupon_code TEXT, total_cents INTEGER NOT NULL, customer_name TEXT, customer_email TEXT, ship_line1 TEXT, ship_line2 TEXT, ship_city TEXT, ship_state TEXT, ship_postal TEXT, ship_country TEXT, tracking_number TEXT, emails_sent INTEGER NOT NULL DEFAULT 0, review_token TEXT, review_requested_at TEXT, marketing_consent INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, paid_at TEXT, shipped_at TEXT);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, offer_id TEXT NOT NULL, name TEXT NOT NULL, unit_price_cents INTEGER NOT NULL, qty INTEGER NOT NULL, line_total_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS contact_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL, subject TEXT NOT NULL, message TEXT NOT NULL, ip TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL UNIQUE, name TEXT NOT NULL, rating INTEGER NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, sleep_position TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscribers (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, source TEXT NOT NULL, quiz_result TEXT, cart_json TEXT, cart_updated_at TEXT, reminder_sent_at TEXT, restore_token TEXT NOT NULL, unsubscribed INTEGER NOT NULL DEFAULT 0, converted INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
